from __future__ import annotations
import importlib.util
from pathlib import Path
kage_bridge = _app.bridge
_kage = kage_bridge.module('rules', 'kage.policy.card_gate')
_owner = kage_bridge.deployment().owner
GATE = _kage.CardGate(language=_owner.language, owner_key=_owner.key, owner_name=_owner.short_name)
WAITING_ON = GATE.waiting_on
WHY_OWNER = _kage.WHY_OWNER
FAILURE_TYPES = _kage.FAILURE_TYPES
(DECIDE_MAX, LINE_MAX) = (_kage.DECIDE_MAX, _kage.LINE_MAX)
(PR_PARTS, PLAN) = (GATE.pr_parts, GATE.plan)
FIELDS = ('decide', 'waiting', 'waiting_on', _app.key_name('why_owner'), 'checked', *dict(PR_PARTS), *dict(PLAN))
(DECISION_RE, FILLER_RE, WAIT_RE, SINCE_RE) = (GATE.decision_re, GATE.filler_re, GATE.wait_re, GATE.since_re)
(OWNER_RE, FAILURE_RE, INFRA_RE) = (GATE.owner_named_re, GATE.failure_re, GATE.infra_re)
(PR_RE, CODE_FILE_RE, COUNTS_RE) = (_kage.PR_RE, _kage.CODE_FILE_RE, _kage.COUNTS_RE)
APPLY_LINE = GATE.apply_line
compose = _kage.compose

def add_args(parser, decide=True, checked=True):
    if decide:
        parser.add_argument('--decide', help=_app.value('card_gate.help'))
    parser.add_argument('--waiting', help='P47 R-0002: who waits on whom, for what, since when')
    parser.add_argument('--waiting-on', choices=WAITING_ON, help='P47 R-0002')
    parser.add_argument(_app.key_name('--why-owner'), choices=WHY_OWNER, help='P47 R-0004, only with --waiting-on person')
    if checked:
        parser.add_argument('--checked', action='append', default=[], help='P47 R-0003: what you looked at and saw, once per check (2+ for an auth / 403 / timeout)')
    for (key, zh) in PR_PARTS + PLAN:
        parser.add_argument('--' + key.replace('_', '-'), help=f"P47 {('R-0005' if key in dict(PR_PARTS) else 'R-0006')}: {zh}")

def fields(args, **extra):
    return {**{k: getattr(args, k, None) for k in FIELDS}, **extra}

def check(rt, gate, *, text='', failure=False):
    gate = {'why_owner' if k == _app.key_name('why_owner') else k: v for (k, v) in gate.items()}
    return GATE.check(rt, gate, text=text, failure=failure)

def open_limit(rt, db, task_id, replaced=None, now=None):
    return GATE.open_limit(rt, db, task_id, replaced, now)

